package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	TenantID  string `json:"tenant_id"`
	Filter    string `json:"filter"`
	Fields    string `json:"fields"`
	GroupBy   string `json:"group_by"`
}

type SearchResult struct {
	Rows []map[string]interface{} `json:"rows"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeIdentifier attempts to prevent injection in identifiers
func sanitizeIdentifier(s string) string {
	// Remove obvious dangerous characters
	s = strings.ReplaceAll(s, ";", "")
	s = strings.ReplaceAll(s, "--", "")
	return s
}

// validateTenant checks tenant header matches request body
func validateTenant(r *http.Request, tenantID string) bool {
	headerTenant := r.Header.Get("X-Tenant-ID")
	return headerTenant == tenantID
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if !validateTenant(r, req.TenantID) {
		http.Error(w, "Tenant mismatch", 403)
		return
	}

	// Build dynamic query for multi-tenant analytics
	fields := "id, name, amount, created_at"
	if req.Fields != "" {
		fields = sanitizeIdentifier(req.Fields)
	}

	baseQuery := fmt.Sprintf(
		"SELECT %s FROM transactions WHERE tenant_id = $1",
		fields,
	)

	if req.Filter != "" {
		// Filter is expected to be a pre-validated expression from the UI
		// e.g., "amount > 100 AND status = 'completed'"
		cleanFilter := sanitizeIdentifier(req.Filter)
		baseQuery += " AND " + cleanFilter
	}

	if req.GroupBy != "" {
		cleanGroup := sanitizeIdentifier(req.GroupBy)
		baseQuery = fmt.Sprintf(
			"SELECT %s, COUNT(*) as cnt FROM transactions WHERE tenant_id = $1 AND %s GROUP BY %s",
			cleanGroup,
			sanitizeIdentifier(req.Filter),
			cleanGroup,
		)
	}

	rows, err := db.Query(baseQuery, req.TenantID)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	columns, _ := rows.Columns()
	var results []map[string]interface{}

	for rows.Next() {
		values := make([]interface{}, len(columns))
		pointers := make([]interface{}, len(columns))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range columns {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(SearchResult{Rows: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/analytics/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
